const results = await Promise.all([
  tools.mcp__lean_lsp__lean_diagnostic_messages({file_path:"AlgebraicJacobian/Picard/Pic0RankOneCanonicalDivisorFree.lean",timeout_s:30}),
  tools.mcp__lean_lsp__lean_hover_info({file_path:"AlgebraicJacobian/Picard/Pic0RankOneCanonicalDivisorFree.lean",line:394,column:19}),
  tools.mcp__lean_lsp__lean_hover_info({file_path:"AlgebraicJacobian/Picard/Pic0RankOneFibrePresentedProducer.lean",line:76,column:11})
]); results.forEach((r,i)=>{ text(`---${i}---`); text(r); });

